//! Deterministic synthetic DNA generators shared across the Rust benchmarks.
//!
//! The real assemblies used during development are private and git-ignored, so
//! benchmarks feed on reproducible synthetic sequences generated by a small
//! seeded LCG.  Output is identical per seed, keeping CodSpeed's instruction
//! count stable across runs.

// Not every benchmark uses every helper; silence dead-code warnings per target.
#![allow(dead_code)]

/// A minimal reproducible pseudo-random generator (SplitMix64).
struct Rng(u64);

impl Rng {
    fn new(seed: u64) -> Self {
        Rng(seed)
    }

    fn next_u64(&mut self) -> u64 {
        // SplitMix64: fast, deterministic, good enough for test data.
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }
}

const BASES: [u8; 4] = [b'A', b'C', b'G', b'T'];

/// Generate a deterministic random DNA sequence of `length` bases.
pub fn random_dna(length: usize, seed: u64) -> Vec<u8> {
    let mut rng = Rng::new(seed);
    (0..length)
        .map(|_| BASES[(rng.next_u64() & 3) as usize])
        .collect()
}

/// Complement a single ACGT base.
fn complement(b: u8) -> u8 {
    match b {
        b'A' => b'T',
        b'T' => b'A',
        b'C' => b'G',
        b'G' => b'C',
        _ => b'N',
    }
}

/// Reverse complement of a DNA slice.
pub fn revcomp(seq: &[u8]) -> Vec<u8> {
    seq.iter().rev().map(|&b| complement(b)).collect()
}

/// Build a homologous `(query, target)` pair with point mutations and planted
/// reverse-complement inversions.
///
/// The target is a mutated copy of the query (substitution rate ~`divergence`)
/// with `n_inversions` evenly spaced segments reverse-complemented, so both the
/// forward and reverse matching paths are exercised.
pub fn homologous_pair(
    length: usize,
    seed: u64,
    divergence: f64,
    n_inversions: usize,
) -> (Vec<u8>, Vec<u8>) {
    let query = random_dna(length, seed);
    let mut target = query.clone();
    let mut rng = Rng::new(seed ^ 0xDEAD_BEEF);

    // Point substitutions.
    let threshold = (divergence * u64::MAX as f64) as u64;
    for base in target.iter_mut() {
        if rng.next_u64() < threshold {
            *base = BASES[(rng.next_u64() & 3) as usize];
        }
    }

    // Planted reverse-complement segments.
    if n_inversions > 0 && length > 0 {
        let seg = (length / (n_inversions * 4)).max(1);
        for j in 0..n_inversions {
            let start = (j * 2 + 1) * (length / (n_inversions * 2 + 1));
            let end = (start + seg).min(length);
            if end > start {
                let rc = revcomp(&target[start..end]);
                target[start..end].copy_from_slice(&rc);
            }
        }
    }

    (query, target)
}
